func (b *tailBuffer) Write(p []byte) (int, error) {
	b.data = append(b.data, p...)
	if len(b.data) > b.capacity {
		b.data = b.data[len(b.data)-b.capacity:]
		b.trimmed = true
	}
	return len(p), nil
}

